my ($grid) = @_;
my $n = @$grid;
my $area = 0;

for my $i (0 .. $n - 1) {
for my $j (0 .. $n - 1) {
next if $grid->[$i][$j] == 0;
$area += 4 * $grid->[$i][$j] + 2; # top and bottom + sides
$area -= 2 * min($grid->[$i][$j], $grid->[$i - 1][$j]) if $i > 0; # subtract area shared with top neighbor
$area -= 2 * min($grid->[$i][$j], $grid->[$i][$j - 1]) if $j > 0; # subtract area shared with left neighbor
}
}

return $area;
}

