my %order_map;

for my $i (0 .. length($order) - 1) {
$order_map{substr($order, $i, 1)} = $i;
}

for my $i (0 .. @$words - 2) {
return 0 unless in_alien_order($words->[$i], $words->[$i + 1], \%order_map);
}

return 1;
}

sub in_alien_order {
my ($word1, $word2, $order_map) = @_;
my $len = length($word1) < length($word2) ? length($word1) : length($word2);

for my $i (0 .. $len - 1) {
my $char1 = substr($word1, $i, 1);
my $char2 = substr($word2, $i, 1);

if ($order_map->{$char1} < $order_map->{$char2}) {
return 1;
} elsif ($order_map->{$char1} > $order_map->{$char2}) {
return 0;
}
}

return length($word1) <= length($word2);
}

