use warnings;

sub max_lights_to_turn_off {
my ($positions, $dist) = @_;

my $count = 0;

for (my $i = 1; $i < @$positions - 1; $i++) {
if ($positions->[$i + 1] - $positions->[$i - 1] <= $dist) {
$count++;
$i++; # Skip the next light as it can't be turned off if this one is off
}
}

return $count;
}

